{
  "items": [
    {
      "title": "German Environment Agency (UBA) – Environmental Data Portal",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data",
      "justification": "Official environmental data portal maintained by Germany's Federal Environment Agency (Umweltbundesamt). Provides historical and recent environmental statistics covering air quality, greenhouse gas emissions, water quality, land use, waste management, and environmental protection. Particularly useful for examining environmental trends in Germany throughout the 2010s and 2020s. Includes downloadable datasets, indicators, and monitoring results."
    },
    {
      "title": "Germany – National Greenhouse Gas Emissions Inventory (1990–2024)",
      "url_or_doi": "https://www.umweltbundesamt.de/themen/klima-energie/treibhausgas-emissionen/daten-berichte",
      "justification": "Official annual greenhouse gas emissions dataset published by the German Environment Agency. Covers carbon dioxide, methane, nitrous oxide, and other greenhouse gases, with emissions categorized by economic sector. Includes data from 2010 through 2024, making it valuable for analyzing Germany's climate change mitigation efforts, emissions reductions, and progress toward national climate targets."
    },
    {
      "title": "UBA DataCube – Greenhouse Gas Emissions by German Climate Protection Act Sectors",
      "url_or_doi": "https://datacube.uba.de/vis?df%5Bag%5D=UBA&df%5Bds%5D=ds-dc-release&df%5Bid%5D=DF_CLIMATE_EMISSIONS_GHG_TRENDS_KSG&df%5Bvs%5D=2026.0&lc=de&pg=0&snb=10&tm=treibhausgase",
      "justification": "Structured statistical dataset from Germany's Federal Environment Agency showing greenhouse gas emissions by sector under the Federal Climate Protection Act. Supports analysis of emissions from energy production, transportation, buildings, industry, agriculture, and land use. Includes historical observations covering the 2010s and 2020s, making it suitable for quantitative climate policy research."
    },
    {
      "title": "German Environment Agency – Air Quality in Germany: Open Data",
      "url_or_doi": "https://luftdaten.umweltbundesamt.de/index.php/en/air-quality-germany-open-data-everyone",
      "justification": "Official air pollution monitoring dataset covering Germany. Contains measurements collected from more than 400 monitoring stations across the country. Includes pollutants such as particulate matter, nitrogen dioxide, and ozone. Historical observations support investigations into air pollution trends during the 2010s and 2020s, including changes associated with transportation policies, industrial activity, and environmental regulations."
    },
    {
      "title": "German Environment Agency – Environmental Indicators Database",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data/environment-indicators/report",
      "justification": "Comprehensive collection of environmental indicators maintained by the German Environment Agency. Includes indicators for biodiversity, landscape quality, air pollution, groundwater nitrate concentrations, river ecological status, land consumption, and waste management. Historical time series provide opportunities to investigate environmental changes in Germany during the 2010s and 2020s. Users can select indicators and download data for further analysis."
    },
    {
      "title": "Federal Agency for Nature Conservation – Protected Landscape Areas in Germany",
      "url_or_doi": "https://data.europa.eu/data/datasets/8dceff1a-7bc1-4a49-9c08-a3f6b37f1b2b",
      "justification": "Official geospatial dataset compiled by Germany's Federal Agency for Nature Conservation (Bundesamt für Naturschutz). Provides information about designated landscape protection areas throughout Germany. The dataset combines information from German federal states and is updated annually. Particularly relevant for examining conservation geography, protected landscapes, and spatial patterns of nature protection during the 2020s. The listed dataset has a 2023 reference period."
    },
    {
      "title": "Federal Agency for Nature Conservation – Protected Areas in Germany (WMS)",
      "url_or_doi": "https://data.europa.eu/data/datasets/8b6394ba-749e-4d6e-94f5-7f1939b2a873",
      "justification": "Official geospatial data service containing information about protected areas across Germany, including national parks, nature reserves, biosphere reserves, nature parks, and Natura 2000 sites. Integrates conservation information from federal and state authorities. Includes reference datasets from 2019 through 2025, providing evidence of conservation designations during the late 2010s and 2020s. Suitable for GIS analysis of protected-area distribution and conservation planning."
    },
    {
      "title": "Federal Agency for Nature Conservation – Protected Areas in Germany (WFS)",
      "url_or_doi": "https://data.europa.eu/data/datasets/bec888f9-ba0c-42dc-846e-177b8265dafa?locale=de",
      "justification": "Official Web Feature Service providing access to spatial information on protected areas in Germany. Useful for extracting and analyzing geographic features associated with nature conservation. Supports research into the distribution of protected habitats, conservation designations, and spatial relationships between protected areas and other environmental characteristics. Particularly relevant to conservation studies focused on the 2020s."
    },
    {
      "title": "Global Biodiversity Information Facility (GBIF) – Biodiversity Occurrence Records for Germany",
      "url_or_doi": "https://www.gbif.org/country/DE/about",
      "justification": "International biodiversity data infrastructure providing species occurrence records for Germany. Includes observations and specimen records for animals, plants, fungi, and other organisms. Records can be examined by year of occurrence, making the resource particularly useful for biodiversity research covering 2010–2026. Supports investigations into species distributions, biodiversity monitoring, habitat conservation, and changes in recorded species occurrences. Researchers should account for variation in sampling effort when analyzing trends."
    },
    {
      "title": "European Environment Agency – Bathing Water Quality Monitoring Dataset (1990–2025)",
      "url_or_doi": "https://www.eea.europa.eu/en/datahub/datahubitem-view/c3858959-90da-4c1b-b9ca-492db0e514df",
      "justification": "European Environment Agency dataset containing historical monitoring information on bathing water quality across European countries, including Germany. Covers inland and coastal bathing waters, with measurements and classifications related to microbiological pollution. Provides observations throughout the 2010s and 2020s, enabling analysis of environmental water quality, public health protection, and improvements in aquatic ecosystem management."
    },
    {
      "title": "European Environment Agency – Bathing Waters with Excellent Quality (2011–2025)",
      "url_or_doi": "https://www.eea.europa.eu/en/datahub/datahubitem-view/d6981ae9-938d-43a9-9c75-c694149f4c8e",
      "justification": "Environmental indicator dataset containing annual statistics on the proportion and number of bathing waters classified as having excellent water quality. Includes Germany and other European countries, with coverage from 2011 through 2025. Supports comparisons of water quality improvements over time and assessments of environmental protection outcomes. Data are available in spreadsheet and machine-readable formats."
    },
    {
      "title": "European Environment Agency – Nationally Designated Protected Areas (2026)",
      "url_or_doi": "https://data.europa.eu/data/datasets/e92c2b84-abee-4da2-b3fe-5be5f0f91066?locale=en",
      "justification": "European dataset documenting nationally designated protected areas, including those in Germany. Contains information about protected sites, designation categories, and relevant legal protection instruments. Useful for examining the status of conservation areas in the 2020s and comparing German protected-area systems with those of other European countries. The 2026 release provides a contemporary snapshot rather than a complete historical time series."
    },
    {
      "title": "European Environment Agency – Germany's Total Greenhouse Gas Emissions",
      "url_or_doi": "https://www.eea.europa.eu/en/europe-environment-2025/countries/germany/total-greenhouse-gas-emissions/",
      "justification": "Country-specific environmental dataset and indicator published by the European Environment Agency. Presents historical trends in greenhouse gas emissions in Germany, including the 2010s and 2020s. Useful for assessing national progress in climate mitigation and comparing German emissions trends with European environmental objectives. Provides standardized emissions statistics suitable for longitudinal analysis."
    },
    {
      "title": "German Environment Agency – Air Quality Development and Historical Pollution Trends",
      "url_or_doi": "https://www.umweltbundesamt.de/en/node/3217",
      "justification": "Official German environmental information resource documenting historical changes in air quality. Provides indicators and supporting monitoring information for assessing long-term pollution trends. Relevant to investigations of particulate matter, nitrogen dioxide, and broader air pollution patterns during the 2010s and 2020s. Useful for evaluating the environmental effects of emission control measures and changes in industrial and transportation activity."
    },
    {
      "title": "European Environment Agency – Bathing Water Quality in Germany: Historical Country Data",
      "url_or_doi": "https://www.eea.europa.eu/en/topics/in-depth/bathing-water/state-of-bathing-water/",
      "justification": "Country-level bathing water quality information published by the European Environment Agency. Includes historical national reports for 2010 through 2024 and country data sheets extending to 2025. Germany-specific information supports analysis of inland and coastal water quality, contamination risks, and environmental monitoring outcomes. Particularly valuable for comparing water quality classifications across multiple years."
    },
    {
      "title": "German Environment Agency – Greenhouse Gas Emissions Indicator",
      "url_or_doi": "https://www.umweltbundesamt.de/en/indicator-greenhouse-gas-emissions",
      "justification": "Official environmental indicator tracking greenhouse gas emissions in Germany over time. Includes historical observations spanning the 2010s and 2020s, with explanations of changes in emissions patterns and the influence of energy production and fossil fuel consumption. Suitable for research on climate policy effectiveness, emissions reduction strategies, and Germany's transition toward lower-carbon energy systems."
    },
    {
      "title": "European Environment Agency – Germany's Environmental Monitoring and Greenhouse Gas Trends",
      "url_or_doi": "https://www.eea.europa.eu/en/europe-environment-2025/countries/germany/total-greenhouse-gas-emissions/",
      "justification": "Standardized European environmental statistics focusing on Germany's greenhouse gas emissions and their development over time. Relevant to studies comparing environmental performance in the 2010s with conditions in the 2020s. Particularly useful for cross-national environmental research because the European Environment Agency applies comparable reporting frameworks across participating countries."
    }
  ]
}
